package main

import (
	"bytes"
	"encoding/json"
	"fmt"
	"strings"
)

type User struct {
	Name  string          `json:"name"`
	Email string          `json:"email,omitempty"`
	Tags  []string        `json:"tags"`
	Extra json.RawMessage `json:"extra,omitempty"`
}

func main() {
	// 结构体转 JSON，空 Email 被 omitempty 省掉
	b, err := json.Marshal(User{Name: "张三", Tags: []string{"go", "json"}})
	fmt.Println("Marshal:", string(b), err)

	// JSON 转回结构体
	var u User
	if err := json.Unmarshal(b, &u); err != nil {
		fmt.Println("Unmarshal 失败:", err)
		return
	}
	fmt.Println("Name:", u.Name, "Email 为空:", u.Email == "")

	// 流式解码，数字用 json.Number 保精度
	dec := json.NewDecoder(strings.NewReader(`{"n":1}{"n":2}`))
	dec.UseNumber()
	for dec.More() {
		var v map[string]any
		_ = dec.Decode(&v)
		fmt.Println("number:", v["n"])
	}

	// Encoder 关闭 HTML 转义后写进 buffer
	var buf bytes.Buffer
	enc := json.NewEncoder(&buf)
	enc.SetEscapeHTML(false)
	_ = enc.Encode("<b>ok</b>")
	fmt.Print("Encoder:", buf.String())
}
